INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1, 'Genesis 1:1', 'Genesis', 1, 1, '&nbsp;په شروع کښې چې کله خُدائ پاک ټول کائنات پېدا کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2, 'Genesis 1:2', 'Genesis', 1, 2, '&nbsp;زمکه خالى وه او هيڅ په کښې نۀ وُو. سمندر هر څۀ ګېر کړى وُو. او هر څيز په توره تيارۀ کښې پټ وو او د خُدائ پاک روح په اوبو حرکت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3, 'Genesis 1:3', 'Genesis', 1, 3, '&nbsp;بيا خُدائ پاک حُکم وکړو چې، ”رڼا دې شى،“ نو رڼا شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4, 'Genesis 1:4', 'Genesis', 1, 4, '&nbsp;خُدائ پاک په دې ليدو خوشحاله وو. بيا هغۀ رڼا د تيارې نه جدا کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5, 'Genesis 1:5', 'Genesis', 1, 5, '&nbsp;او په رڼا يې ”ورځ“ نوم کېښودو او په تيارۀ يې ”شپه.“ شپه تېره شوه او سحر شو. دا وړومبۍ ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6, 'Genesis 1:6', 'Genesis', 1, 6, '&nbsp;بيا خُدائ پاک حُکم وکړو چې، ”د پاسنو او لاندينو اوبو تر مينځه دې فضا جوړه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7, 'Genesis 1:7', 'Genesis', 1, 7, '&nbsp;نو هم داسې وشول. نو خُدائ پاک فضا جوړه کړه چې لاندې اوبۀ د پاس اوبو نه جدا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(8, 'Genesis 1:8', 'Genesis', 1, 8, '&nbsp;هغۀ په دې چت ”آسمان“ نوم کېښودو. شپه تېره شوه او سحر شو. دا دوېمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9, 'Genesis 1:9', 'Genesis', 1, 9, '&nbsp;بيا خُدائ پاک حُکم وکړو، ”د آسمان لاندې اوبۀ دې په يو ځائ راغونډې شى، نو اوچه به راښکاره شى.“ نو هم داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10, 'Genesis 1:10', 'Genesis', 1, 10, '&nbsp;هغۀ په اوچه ”زمکه“ نوم کېښودو او په يو ځائ راغونډو شوو اوبو يې ”سمندر“ نوم کېښودو. او خُدائ پاک د دې په ليدو خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11, 'Genesis 1:11', 'Genesis', 1, 11, '&nbsp;بيا هغۀ حُکم وکړو، ”زمکه دې هر قِسم بوټى رازرغون کړى، هغه ټول بوټى چې غله او مېوه به کوى.“ نو هم داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12, 'Genesis 1:12', 'Genesis', 1, 12, '&nbsp;نو زمکې هغه هر قِسم بوټى زرغون کړل کوم چې غله او مېوه کوى او خُدائ پاک د دې په ليدو خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(13, 'Genesis 1:13', 'Genesis', 1, 13, '&nbsp;شپه تېره شوه او سحر شو. دا درېمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14, 'Genesis 1:14', 'Genesis', 1, 14, '&nbsp;بيا خُدائ پاک حُکم وکړو، ”ځلېدونکى څيزونه دې په آسمان کښې راښکاره شى چې ورځ د شپې نه جدا کړى او چې د ورځو، مياشتو او د کالونو دپاره نښې شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15, 'Genesis 1:15', 'Genesis', 1, 15, '&nbsp;دا به په آسمان کښې زمکې ته ځليږى.“ نو هم داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16, 'Genesis 1:16', 'Genesis', 1, 16, '&nbsp;نو خُدائ پاک هغه دوه غټ ځلېدونکى څيزونه جوړ کړل، نمر به د ورځې ځليږى او سپوږمۍ به د شپې ځليږى، هغۀ ستورى هم پېدا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17, 'Genesis 1:17', 'Genesis', 1, 17, '&nbsp;هغۀ دا ځلېدونکى څيزونه په آسمان کښې مقرر کړل چې زمکې له رڼا ورکوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(18, 'Genesis 1:18', 'Genesis', 1, 18, '&nbsp;چې په ورځ او شپه باندې اختيار ولرى او رڼا د تيارې نه جدا کړى. او خُدائ پاک د دې په ليدو خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19, 'Genesis 1:19', 'Genesis', 1, 19, '&nbsp;شپه تېره شوه او سحر شو. دا څلورمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20, 'Genesis 1:20', 'Genesis', 1, 20, '&nbsp;بيا خُدائ پاک حُکم وکړو، ”سمندر دې د ډېر قِسم ساه اخستونکى څيزونو نه ډک شى او هوا دې د مارغانو نه ډکه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21, 'Genesis 1:21', 'Genesis', 1, 21, '&nbsp;نو خُدائ پاک غټې سمندرى بلاګانې پېدا کړې، هر قِسم ساه لرونکى څيزونه چې په اوبو کښې اوسيږى او هر قِسم مارغان يې پېدا کړل. او خُدائ پاک د دې په ليدو خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22, 'Genesis 1:22', 'Genesis', 1, 22, '&nbsp;او خُدائ پاک برکت ورکړو او د اوبو مخلوق ته يې وفرمائيل چې، ”ډېر شئ او سمندر ډک کړئ،“ او مارغانو ته يې وفرمائيل چې، ”زيات شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23, 'Genesis 1:23', 'Genesis', 1, 23, '&nbsp;شپه تېره شوه او سحر شو. دا پينځمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24, 'Genesis 1:24', 'Genesis', 1, 24, '&nbsp;بيا خُدائ پاک حُکم وکړو، ”زمکه دې هر قِسم څاروى او ځنګلى، واړۀ او غټ ځناور پېدا کړى.“ نو هم داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25, 'Genesis 1:25', 'Genesis', 1, 25, '&nbsp;نو خُدائ پاک دا ټول ځناور، څاروې او خزنده پېدا کړل او هغه د دې په ليدو خوشحاله وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26, 'Genesis 1:26', 'Genesis', 1, 26, '&nbsp;بيا خُدائ پاک وفرمائيل، ”اوس به مونږ انسان د خپل صورت په شان جوړ کړُو چې زمونږ په شان شى. هغوئ به په کبانو، مارغانو او په ټولو ځناورو، څاروو او ځنګلى، وړو او غټو ځناورو باندې اختيار لرى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27, 'Genesis 1:27', 'Genesis', 1, 27, '&nbsp;نو خُدائ پاک بنى آدم پېدا کړل او د خپل صورت په شان يې جوړ کړل. هغوئ يې نر او ښځه پېدا کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28, 'Genesis 1:28', 'Genesis', 1, 28, '&nbsp;برکت يې ورکړو او وې فرمائيل، ”ډېر بچى پېدا کړئ، نو ستاسو اولاد به په ټوله دُنيا کښې اوسيږى او زمکه به د هغوئ په لاس کښې وى. زۀ تاسو له په کبانو، مارغانو او په ټولو ځناورو باندې اختيار درکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29, 'Genesis 1:29', 'Genesis', 1, 29, '&nbsp;ما تاسو له د خوراک دپاره هر قِسم غله او هر قِسم مېوې پېدا کړې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30, 'Genesis 1:30', 'Genesis', 1, 30, '&nbsp;خو ټولو ځنګلى ځناورو او ټولو مارغانو له ما د خوراک دپاره واښۀ او شنۀ بوټى پېدا کړى دى.“ نو هم داسې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(31, 'Genesis 1:31', 'Genesis', 1, 31, '&nbsp;خُدائ پاک دا ټول څيزونه وکتل او هغه ډېر خوشحاله وو. شپه تېره شوه او سحر شو. دا شپږمه ورځ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(32, 'Genesis 2:1', 'Genesis', 2, 1, '&nbsp;نو داسې د ټول کائنات جوړېدل پوره شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(33, 'Genesis 2:2', 'Genesis', 2, 2, '&nbsp;خُدائ پاک خپل ټول کارونه پوره کړل او په اوومه ورځ يې څۀ ونۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(34, 'Genesis 2:3', 'Genesis', 2, 3, '&nbsp;هغۀ اوومې ورځې له برکت ورکړو او مقدسه يې وګرځوله، ځکه چې هغۀ په اوومه ورځ پېدايښت پوره کړو او څۀ يې ونۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(35, 'Genesis 2:4', 'Genesis', 2, 4, '&nbsp;او داسې ټول کائنات پېدا شول. د عدن باغ کله چې مالِک خُدائ، خُدائ پاک ټول کائنات جوړ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(36, 'Genesis 2:5', 'Genesis', 2, 5, '&nbsp;په زمکه هيڅ قِسم بوټے نۀ وو او هيڅ تخم زرغون شوے نۀ وو، ځکه چې هغۀ باران نۀ وو ورولے او د زمکې د کروندې هم څوک نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(37, 'Genesis 2:6', 'Genesis', 2, 6, '&nbsp;خو اوبۀ به د زمکې نه راوتلې او زمکه به يې اوبۀ کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(38, 'Genesis 2:7', 'Genesis', 2, 7, '&nbsp;بيا مالِک خُدائ، خُدائ پاک د زمکې نه څۀ خاوره واخستله او آدم يې ترې نه جوړ کړو. خُدائ پاک د هغۀ په سپېږمو کښې د ژوند ساه پو کړه او آدم ژوندے نفس جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(39, 'Genesis 2:8', 'Genesis', 2, 8, '&nbsp;بيا مالِک خُدائ، خُدائ پاک په عدن کښې يو باغ وکَرلو او هغه پېدا کړے آدم يې په کښې مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(40, 'Genesis 2:9', 'Genesis', 2, 9, '&nbsp;هغۀ هلته هر قِسم ښائسته او مېوه‌دارې ونې راشنې کړلې. هغۀ د باغ په مينځ کښې ژوند ورکوونکى ونه او د ښۀ او بد پوهه ورکوونکى ونه ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(41, 'Genesis 2:10', 'Genesis', 2, 10, '&nbsp;په عدن کښې يو درياب به باغ اوبۀ کولو، د عدن بل طرف ته دا په څلورو سيندونو کښې تقسيم شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(42, 'Genesis 2:11', 'Genesis', 2, 11, '&nbsp;د وړومبى سيند نوم فيسون دے، دا د حويلۍ ټول مُلک نه تېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(43, 'Genesis 2:12', 'Genesis', 2, 12, '&nbsp;سوچه سرۀ زر، خوشبودار عطر او اونيکس کاڼى دلته ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(44, 'Genesis 2:13', 'Genesis', 2, 13, '&nbsp;د دوېم سيند نوم جيحون دے، دا د کوش ټول مُلک نه تېريږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(45, 'Genesis 2:14', 'Genesis', 2, 14, '&nbsp;درېم سيند دجله دے، چې د اسور نمرخاتۀ طرف نه تېريږى او څلورم د فرات سيند دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(46, 'Genesis 2:15', 'Genesis', 2, 15, '&nbsp;مالِک خُدائ، خُدائ پاک آدم په باغ عدن کښې مقرر کړو چې په باغ کښې کَرل رېبل کوى او ساتنه يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(47, 'Genesis 2:16', 'Genesis', 2, 16, '&nbsp;مالِک خُدائ، خُدائ پاک هغۀ ته حُکم وکړو، ”تۀ د باغ د هرې ونې مېوه خوړے شې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(48, 'Genesis 2:17', 'Genesis', 2, 17, '&nbsp;خو د هغې ونې نه بغېر کومه چې د ښۀ او بد د پېژندګلو پوهه ورکوى. چې هيڅکله د هغې ونې مېوه ونۀ خورې، کۀ تا وخوړه، نو په هغه ورځ به مړ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(49, 'Genesis 2:18', 'Genesis', 2, 18, '&nbsp;بيا مالِک خُدائ، خُدائ پاک وفرمائيل، ”د آدم دپاره يواځې اوسېدل ښۀ نۀ دى. زۀ به د هغۀ دپاره يوه ښۀ ملګرې جوړه کړم چې د هغۀ مدد به کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(50, 'Genesis 2:19', 'Genesis', 2, 19, '&nbsp;نو هغۀ د زمکې نه څۀ خاوره واخستله او ټول ځناور او مارغان يې ترې نه جوړ کړل. هغه يې بيا آدم له راوستل چې وګورى چې څۀ نومونه ورباندې ږدى، او آدم چې په هر ژوندى څيز څۀ نوم کېښودو نو هم هغه يې نوم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(51, 'Genesis 2:20', 'Genesis', 2, 20, '&nbsp;نو آدم په ټولو مارغانو او ځناورو نومونه کېښودل، خو د آدم دپاره يوه ښۀ ملګرې نۀ وه پېدا شوې چې د هغۀ مدد وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(52, 'Genesis 2:21', 'Genesis', 2, 21, '&nbsp;بيا مالِک خُدائ، خُدائ پاک په آدم دروند خوب راوستلو او چې آدم اودۀ شو، نو هغۀ د آدم نه يوه پوښتۍ راوويسته او هغه ځائ يې ورله په غوښه ډک کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(53, 'Genesis 2:22', 'Genesis', 2, 22, '&nbsp;بيا مالِک خُدائ، خُدائ پاک د آدم د پوښتۍ نه يوه ښځه پېدا کړه او هغۀ له يې راوستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(54, 'Genesis 2:23', 'Genesis', 2, 23, '&nbsp;نو آدم وفرمائيل، ”واه، دا هم زما په شان ده. او زما په شان بدن دے. د دې نوم ”ښځه“ دے، ځکه چې دا د بنى آدم نه راويستلے شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(55, 'Genesis 2:24', 'Genesis', 2, 24, '&nbsp;په دې وجه به سړے خپل مور پلار پرېږدى او د خپلې ښځې سره به يو ځائ شى، او دواړه به يو بدن شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(56, 'Genesis 2:25', 'Genesis', 2, 25, '&nbsp;سړے او ښځه دواړه بربنډ وُو، خو د يو بل نه يې پړده نۀ کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(57, 'Genesis 3:1', 'Genesis', 3, 1, '&nbsp;مالِک خُدائ، خُدائ پاک چې څومره ځناور پېدا کړى وُو مار په کښې د ټولو نه چالاک وو. مار د ښځې نه تپوس وکړو، ”دا رښتيا دى څۀ چې تاسو ته خُدائ پاک فرمائيلى دى چې د باغ د هرې يوې ونې مېوه مۀ خورئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(58, 'Genesis 3:2', 'Genesis', 3, 2, '&nbsp;ښځې جواب ورکړو، ”مونږ ته په باغ کښې د هرې ونې نه د مېوې خوړلو اجازت شته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(59, 'Genesis 3:3', 'Genesis', 3, 3, '&nbsp;خو د هغه ونې د مېوې نه بغېر چې د باغ په مينځ کښې ده. خُدائ پاک مونږ ته فرمائيلى دى چې د هغې ونې مېوه ونۀ خورئ او نه لاس وروړئ، کۀ داسې مو وکړل نو مړۀ به شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(60, 'Genesis 3:4', 'Genesis', 3, 4, '&nbsp;مار جواب ورکړو، ”تاسو به يقيناً نۀ مرئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(61, 'Genesis 3:5', 'Genesis', 3, 5, '&nbsp;خُدائ پاک دا ځکه فرمائيلى دى، چې هغۀ ته پته ده کۀ تاسو د دې مېوه وخوړه نو ستاسو سترګې به وغړيږى، د خُدائ پاک په شان به شئ او په ښۀ او بد به پوهه شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(62, 'Genesis 3:6', 'Genesis', 3, 6, '&nbsp;چې ښځې ونه وليده نو په زړۀ کښې يې راغلل چې دا ونه دومره ښُکلې ده، مېوه به يې څومره خوَږه وى او څومره مزه به وکړى چې هوښيار شُو. نو لږه مېوه يې ترې وشوکوله او وې خوړله. بيا يې لږه ترې نه خاوند له هم ورکړه ځکه چې هغه ورسره وو او هغۀ هم وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(63, 'Genesis 3:7', 'Genesis', 3, 7, '&nbsp;چې دا يې څنګه وخوړه، نو د دوئ سترګې وغړېدلې او پته ورته ولګېده چې دوئ خو بربنډ دى، نو دوئ د اينځر پاڼې وګنډلې او ځانونه يې پرې پټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(64, 'Genesis 3:8', 'Genesis', 3, 8, '&nbsp;د ماښامى په نرۍ نرۍ هوا کښې دوئ د مالِک خُدائ، خُدائ پاک د راتلو آواز واورېدو، نو دوئ په ونو کښې پټ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(65, 'Genesis 3:9', 'Genesis', 3, 9, '&nbsp;خو مالِک خُدائ، خُدائ پاک آدم له آواز ورکړو، ”تۀ چرته يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(66, 'Genesis 3:10', 'Genesis', 3, 10, '&nbsp;هغۀ ورته وفرمائيل، ”ما په باغ کښې ستا د راتلو آواز واورېدو، نو زۀ ويرېدم او ستا نه پټ شوم، ځکه چې بربنډ وم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(67, 'Genesis 3:11', 'Genesis', 3, 11, '&nbsp;نو خُدائ پاک ترې تپوس وکړو، ”تا ته چا ووئيل چې تۀ بربنډ يې؟ تا هغه مېوه وخوړه څۀ چې د کومې نه ما منع کړے وې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(68, 'Genesis 3:12', 'Genesis', 3, 12, '&nbsp;آدم جواب ورکړو، ”کومه ښځه چې تا زما سره کړې ده هغې ما له هغه مېوه راکړه، نو ما وخوړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(69, 'Genesis 3:13', 'Genesis', 3, 13, '&nbsp;نو مالِک خُدائ، خُدائ پاک د ښځې نه تپوس وکړو، ”تا ولې داسې وکړل؟“ هغې ورته وفرمائيل، ”زۀ خو مار دوکه کړم او ما وخوړله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(70, 'Genesis 3:14', 'Genesis', 3, 14, '&nbsp;بيا مالِک خُدائ، خُدائ پاک مار ته وفرمائيل، ”د دې کار په وجه به ستا دا سزا وى، په ټولو ځناورو کښې به صِرف تۀ لعنتى شې. د اوس نه به په خېټه تلل کوې او چې ترڅو ژوندے يې خاورې به خورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
